sources=[];claims=[]
def src(id,file,url,publisher,tier,quote,locator,supports,kind='document',extra=None,published='unknown'):
    text=(D/file).read_text();assert quote in text,(id,quote)
    row=dict(id=id,url=url,canonical_url=url,publisher=publisher,tier=tier,published_at=published,retrieved_at=now,quote=quote,locator=locator,origin_id=id,origin_basis='已读取原始文件或具名数据供应商的展示页；同一文件不同片段不视为独立来源',supports=supports,evidence_kind=kind,access_status='ok',selection=dict(selected=True,reason='直接回答同期表现或经营机制',relevance='direct',purpose='波动归因',priority='decisive'))
    if extra: row.update(extra)
    sources.append(row)
def claim(id,text,type='fact',ss=None,basis=None,**kw):
    row=dict(id=id,text=text,type=type,as_of=now,sources=[{'source_id':s} for s in (ss or [])]);row.update(kw)
    if basis: row['basis']=basis
    claims.append(row)
